# Region for operators that existed before D051, from their currency. Others are set in the platform portal.
KNOWN = {"YER": ("YE", "ر.ي", "+967"), "SAR": ("SA", "ر.س", "+966"), "AED": ("AE", "د.إ", "+971"), "OMR": ("OM", "ر.ع", "+968")}


def fill_region(apps, schema_editor):
    Tenant = apps.get_model("tenancy", "Tenant")
    for tenant in Tenant.objects.all():
        country, symbol, phone = KNOWN.get(tenant.currency, ("", "", ""))
        tenant.country = tenant.country or country
        tenant.currency_symbol = tenant.currency_symbol or symbol
        tenant.phone_country_code = tenant.phone_country_code or phone
        tenant.save(update_fields=["country", "currency_symbol", "phone_country_code"])


